// GBP Layer 1 agent draft v0.1 (2026-09-05): select the latest usable GBP market
// snapshot and expose the GBP input contract. Fails closed when no GBP snapshot
// with a GBP/USD price exists, and when the only available snapshot is stale.

const rows = $input.all().map((item) => item.json);

function hasValue(v) {
  return v !== null && v !== undefined && v !== "";
}

// Latest GBP trading weekday on or before the previous UTC day. Used so that a
// Monday run can accept a Friday snapshot (weekend closure) but a Tuesday run
// cannot accept a Friday snapshot.
function latestGbpWeekdayOnOrBeforePreviousDay(date) {
  const d = new Date(date.getTime());
  d.setUTCDate(d.getUTCDate() - 1);
  let guard = 0;
  while ((d.getUTCDay() === 0 || d.getUTCDay() === 6) && guard < 5) {
    d.setUTCDate(d.getUTCDate() - 1);
    guard += 1;
  }
  return d.toISOString().slice(0, 10);
}

function isUsableGbpSnapshot(row) {
  return Boolean(row.snapshot_date && row.run_time_et && hasValue(row.gbpusd_price));
}

function isStaleGbpSnapshot(row, now) {
  const runTime = new Date(row.run_time_et || row.created_at || 0).getTime();
  const ageHours = (now.getTime() - runTime) / 3600000;
  const latestExpected = latestGbpWeekdayOnOrBeforePreviousDay(now);
  return ageHours > 26 && String(row.snapshot_date) < latestExpected;
}

const now = new Date();

const sortedRows = rows
  .filter((r) => r.snapshot_date && r.run_time_et)
  .sort((a, b) => {
    const bTime = new Date(b.run_time_et || b.created_at || 0).getTime();
    const aTime = new Date(a.run_time_et || a.created_at || 0).getTime();
    return bTime - aTime;
  });

const usableRows = sortedRows.filter(isUsableGbpSnapshot);

const snapshot =
  usableRows.find((r) => r.collector_version === "gbp_collector_draft_v0_1" && !isStaleGbpSnapshot(r, now)) ||
  usableRows.find((r) => !isStaleGbpSnapshot(r, now)) ||
  null;

if (!snapshot) {
  const freshest = sortedRows[0];
  const detail = freshest
    ? `latest row snapshot_date=${freshest.snapshot_date} run_time_et=${freshest.run_time_et} has gbpusd_price=${hasValue(freshest.gbpusd_price)}`
    : "no GBP snapshot rows found";
  throw new Error(`No usable GBP market snapshot found (${detail})`);
}

const quality = (() => {
  if (!snapshot.data_quality) return {};
  if (typeof snapshot.data_quality === "object") return snapshot.data_quality;
  try {
    return JSON.parse(snapshot.data_quality);
  } catch (error) {
    return {};
  }
})();


function numOrNull(v) {
  if (!hasValue(v)) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function parseMaybeJson(v) {
  if (!hasValue(v)) return null;
  if (typeof v === "object") return v;
  try {
    return JSON.parse(v);
  } catch (error) {
    return v;
  }
}

const missingInputs = [];
const warnings = [];

function requireInput(key, label = key) {
  const value = snapshot[key];
  if (!hasValue(value)) {
    missingInputs.push(label);
    return null;
  }
  return value;

const gbpInputPack = {
  snapshot_id: snapshot.id || null,
  run_time_et: snapshot.run_time_et,
  snapshot_date: snapshot.snapshot_date,
  collector_version: snapshot.collector_version || null,

  snapshot_selection: {
    selected_from_rows: sortedRows.length,
    selected_by: selectedBy,
    missing_required_inputs_for_gbp: missingInputs,
    data_quality: quality,
    warnings,
    top_5_rows_seen_by_workflow: debugTopRows
  },

  available_inputs: {
    gbpusd_price: requireInput("gbpusd_price"),
    gbpusd_d1_pct: numOrNull(snapshot.gbpusd_d1_pct),
    gbpusd_d5_pct: numOrNull(snapshot.gbpusd_d5_pct),
    gbpusd_d20_pct: numOrNull(snapshot.gbpusd_d20_pct),

    vix_level: requireInput("vix_level"),
    vix_d1: numOrNull(snapshot.vix_d1),
    vix_d5: numOrNull(snapshot.vix_d5),

    dxy_level: numOrNull(snapshot.dxy_level),
    dxy_d1: numOrNull(snapshot.dxy_d1),
    dxy_d5: numOrNull(snapshot.dxy_d5),
    dxy_d20: numOrNull(snapshot.dxy_d20),

    us_2y_yield: numOrNull(snapshot.us_2y_yield),
    us_2y_d5_bps: numOrNull(snapshot.us_2y_d5_bps),
    us_2y_d20_bps: numOrNull(snapshot.us_2y_d20_bps),

    uk_10y_yield: numOrNull(snapshot.uk_10y_yield),
    uk_10y_d5_bps: numOrNull(snapshot.uk_10y_d5_bps),

    uk_2y_yield: numOrNull(snapshot.uk_2y_yield),
    uk_2y_d5_bps: numOrNull(snapshot.uk_2y_d5_bps),
    uk_2y_d20_bps: numOrNull(snapshot.uk_2y_d20_bps),

    us_uk_2y_spread: numOrNull(snapshot.us_uk_2y_spread),
    us_uk_2y_spread_d5_bps: numOrNull(snapshot.us_uk_2y_spread_d5_bps),
    us_uk_2y_spread_d20_bps: numOrNull(snapshot.us_uk_2y_spread_d20_bps),

    boe_bias: snapshot.boe_bias ?? null,
    latest_uk_event: parseMaybeJson(snapshot.latest_uk_event),
    uk_composite_pmi: numOrNull(snapshot.uk_composite_pmi),
    uk_composite_pmi_direction: snapshot.uk_composite_pmi_direction ?? null,
    uk_stress_flag: snapshot.uk_stress_flag ?? null,

    equities_regime: snapshot.equities_regime ?? null,
    global_growth_regime: snapshot.global_growth_regime ?? null
  },

  missing_inputs_must_be_scored_neutral: [
    "boe_bias if unavailable",
    "uk_2y_d5_bps or uk_2y_d20_bps if unavailable",
    "us_uk_2y_spread_d5_bps or us_uk_2y_spread_d20_bps if unavailable",
    "latest_uk_event if unavailable",
    "uk_composite_pmi or uk_composite_pmi_direction if unavailable",
    "gbpusd_d1_pct, gbpusd_d5_pct or gbpusd_d20_pct if unavailable",
    "dxy_d1, dxy_d5 or dxy_d20 if unavailable",
    "uk_stress_flag if unavailable",
    "global_growth_regime if unavailable",
    "vix_level, vix_d1 or vix_d5 if unavailable"
  ],

  gbp_factor_map: {
    F1: "BoE policy bias",
    F2: "UK 2Y yield delta",
    F3: "US-UK 2Y spread delta",
    F4: "UK economic surprise",
    F5: "UK PMI trend",
    F6: "GBP own-price delta",
    F7: "DXY confirmation",
    F8: "Risk appetite / VIX regime",
    F9: "Global growth regime",
    F10: "UK stress"
  }
};

return [{ json: gbpInputPack }];

}

const selectedBy = snapshot.collector_version === "gbp_collector_draft_v0_1"
  ? "latest_gbp_draft_usable_snapshot"
  : "latest_gbp_usable_snapshot";

const debugTopRows = sortedRows.slice(0, 5).map((r, index) => ({
  rank: index + 1,
  id: r.id || null,
  created_at: r.created_at || null,
  run_time_et: r.run_time_et,
  snapshot_date: r.snapshot_date,
  collector_version: r.collector_version || null,
  source_status: r.source_status || null,
  gbpusd_price: r.gbpusd_price || null,
  gbp_usable: isUsableGbpSnapshot(r),
  stale: isStaleGbpSnapshot(r, now)
}));

// GBP Layer 1 agent draft v0.1: combine the GBP logic document with the selected
// GBP input pack for the model prompt.
const logicItem = $("Get GBP Logic Document").first().json;
const inputPack = $("Build GBP Input Pack").first().json;

let logicDocument = logicItem.content || "";

if (logicItem.encoding === "base64") {
  logicDocument = Buffer.from(logicDocument, "base64").toString("utf8");
}

return [
  {
    json: {
      logic_document: logicDocument,
      market_snapshot: inputPack
    }
  }
];

// GBP Layer 1 agent draft v0.1: tolerant OpenAI output parser (object|string) that
// maps the model JSON into the agent_outputs row contract for the GBP 24H call.
const openAiItem = $input.first().json;

let raw =
  openAiItem.output?.[0]?.content?.[0]?.text ??
  openAiItem.output?.[0]?.content?.[0] ??
  openAiItem.text ??
  openAiItem.message ??
  openAiItem;

if (!raw) {
  throw new Error("No OpenAI output found");
}

let report;

if (typeof raw === "object") {
  report = raw;
} else {
  try {
    report = JSON.parse(String(raw));
  } catch (error) {
    throw new Error(`OpenAI returned invalid JSON: ${error.message}. Raw text: ${String(raw).slice(0, 1000)}`);
  }
}

const inputPack = $("Build GBP Input Pack").first().json || {};
const marketInputs = inputPack.available_inputs || {};

function pct(value) {
  if (value === null || value === undefined || value === "") return null;
  const match = String(value).match(/(\d+(\.\d+)?)/);
  return match ? Number(match[1]) : null;
}

function reasonFor24h() {
  return report.reason_24h || report.reasoning_summary || "";
}

return [
  {
    json: {
      snapshot_id: inputPack.snapshot_id || null,
      agent_name: "GBP",
      layer: 1,

      run_time_et: inputPack.run_time_et || new Date().toISOString(),
      snapshot_date: inputPack.snapshot_date || new Date().toISOString().slice(0, 10),

      market_inputs: marketInputs,
      snapshot_selection: inputPack.snapshot_selection || null,

      call_24h_direction: report.direction_24h || report.call_24h_direction || null,
      call_24h_conviction: pct(report.conviction_24h ?? report.call_24h_conviction),
      call_24h_reason: reasonFor24h(),

      direction_24h: report.direction_24h || null,
      conviction_24h: pct(report.conviction_24h),

      factor_breakdown: report.factor_breakdown || {},
      weighted_score: report.weighted_score || null,
      conviction_model: report.conviction_model || null,

      missing_inputs: report.missing_inputs || [],
      reasoning_summary: report.reasoning_summary || "",

      risk_flags: report.risk_flags || [],
      warnings: report.warnings || [],

      full_output: {
        ...report,
        market_inputs_seen_by_workflow: marketInputs,
        snapshot_selection: inputPack.snapshot_selection || null
      },

      raw_agent_output: report,

      logic_document: "agent_gbp_direction.md",
      logic_document_version: report.logic_document_version || "0.1_research_baseline",

      score_bullish: report.score_bullish ?? null,
      score_bearish: report.score_bearish ?? null,
      score_neutral: report.score_neutral ?? null
    }
  }
];

// GBP Layer 1 agent draft v0.1: deterministic 24H verdict gate. Recomputes the 24H
// direction/conviction from the factor signals in the model output using the
// logic-document weight table (agent_gbp_direction.md), overriding any model
// confidence so the published verdict is deterministic.
const item = $input.first().json;
const breakdown = item.factor_breakdown || {};

// Must stay identical to the logic-document factor table and to
// backtester/replay/gbp/gbp_replay_core.js LIVE_24H_FACTOR_WEIGHTS.
const WEIGHTS = {
  F1: 20,
  F2: 16,
  F3: 20,
  F4: 12,
  F5: 8,
  F6: 10,
  F7: 6,
  F8: 4,
  F9: 2,
  F10: 2
};

function normaliseSignal(factor) {
  const signal = String((factor && factor.signal) || "").toUpperCase();
  if (signal === "BULLISH" || signal === "BEARISH") return signal;
  return "NEUTRAL";
}

let bullishWeight = 0;
let bearishWeight = 0;
let neutralWeight = 0;
const factorSignals = {};

for (const key of Object.keys(WEIGHTS)) {
  const signal = normaliseSignal(breakdown[key]);
  const weight = WEIGHTS[key];
  factorSignals[key] = signal;
  if (signal === "BULLISH") bullishWeight += weight;
  else if (signal === "BEARISH") bearishWeight += weight;
  else neutralWeight += weight;
}

const active = bullishWeight + bearishWeight;
const missingFactorCount = Object.keys(WEIGHTS).filter((key) => !breakdown[key] || !breakdown[key].signal).length;

let direction = "NO_CLEAR_BIAS";
let conviction = 0;
let weightedScore = null;
let convictionModel = null;

if (active > 0) {
  const bullishArgument = Math.round((bullishWeight / active) * 100);
  const bearishArgument = Math.round((bearishWeight / active) * 100);
  const netEdge = bullishArgument - bearishArgument;
  const winningSide = bullishArgument > bearishArgument ? "BULLISH" : bearishArgument > bullishArgument ? "BEARISH" : "NO_CLEAR_BIAS";

  direction = winningSide === "NO_CLEAR_BIAS" ? "NO_CLEAR_BIAS" : Math.abs(netEdge) < 20 ? `${winningSide}_LEAN` : winningSide;
  conviction = winningSide === "BULLISH" ? bullishArgument : winningSide === "BEARISH" ? bearishArgument : 0;

  weightedScore = {
    bullish_weight: bullishWeight,
    bearish_weight: bearishWeight,
    neutral_weight: neutralWeight,
    active_weight: active,
    weight_margin: Math.abs(bullishWeight - bearishWeight)
  };

  convictionModel = {
    bullish_argument_pct: bullishArgument,
    bearish_argument_pct: bearishArgument,
    neutral_evidence_pct: neutralWeight,
    directional_participation_pct: active,
    net_edge_pct: netEdge,
    winning_side: winningSide,
    final_conviction: conviction
  };
}

return [
  {
    json: {
      ...item,
      direction_24h: direction,
      conviction_24h: conviction,
      call_24h_direction: direction,
      call_24h_conviction: conviction,
      call_24h_reason: item.call_24h_reason || "Deterministic 24H gate: no active directional weight.",
      weighted_score: weightedScore,
      conviction_model: convictionModel,
      deterministic_24h_gate: {
        active_weight: active,
        missing_factor_count: missingFactorCount,
        factor_signals: factorSignals
      }
    }
  }
];
